/* Observes displayed battle modes at fixed ticks; never changes battle physics or RNG. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.PatternBattleTally=api;})(globalThis,function(){
'use strict';
const labels=Object.freeze(['Finding the other beetle','Guarding the edge','Looking for a side push','Bracing & pushing','Pushing','Tracking the opponent','Wandering','Curious approach','Social approach','Winding up horn lift','Winding up spring jump','Winding up bombardier puff','Spring jump','Lifted — regaining grip','Puff — reorienting','Recovering landing','Flipped — righting itself']);
function create(match){return {version:1,ticks:0,fighters:match.fighters.map(f=>({id:f.beetle.id,name:f.beetle.name||'',rows:labels.map(behavior=>({behavior,count:0,ticks:0}))})),previous:[null,null]};}
function observe(tally,match){if(match.tick===tally.ticks)return;if(match.tick!==tally.ticks+1)throw Error('Observe each battle tick before advancing again.');for(const [i,f]of match.fighters.entries()){const behavior=f.mode,rows=tally.fighters[i].rows;let row=rows.find(r=>r.behavior===behavior);if(!row){row={behavior,count:0,ticks:0};rows.push(row);}if(tally.previous[i]!==behavior)row.count++;row.ticks++;tally.previous[i]=behavior;}tally.ticks=match.tick;}
function snapshot(tally){return {version:1,ticks:tally.ticks,fighters:tally.fighters.map(f=>({id:f.id,name:f.name,rows:f.rows.map(r=>({...r}))}))};}
function validate(tally,record){const int=(v,max)=>Number.isInteger(v)&&v>=0&&v<=max;if(!tally||tally.version!==1||!int(tally.ticks,3606)||tally.ticks!==Math.round(record.seconds*60)||!Array.isArray(tally.fighters)||tally.fighters.length!==2)throw Error('Invalid battle behavior tally.');for(const [i,f]of tally.fighters.entries()){if(!f||f.id!==record.fighters[i].id||f.name!==record.fighters[i].name||!Array.isArray(f.rows)||f.rows.length<17||f.rows.length>32||new Set(f.rows.map(r=>r?.behavior)).size!==f.rows.length||labels.some(label=>!f.rows.some(r=>r.behavior===label)))throw Error('Invalid behavior tally fighter.');let total=0;for(const r of f.rows){if(!r||typeof r.behavior!=='string'||!r.behavior.length||r.behavior.length>80||!int(r.count,tally.ticks)||!int(r.ticks,tally.ticks)||r.count>r.ticks||(r.ticks>0&&r.count===0))throw Error('Invalid behavior tally row.');total+=r.ticks;}if(total!==tally.ticks)throw Error('Behavior times must equal the battle duration.');}return tally;}
function marks(count){if(!count)return '—';const groups=Math.floor(count/5),rest='|'.repeat(count%5);return groups>4?'||||/ × '+groups+(rest?' + '+rest:''):[...Array(groups).fill('||||/'),rest].filter(Boolean).join(' ');}
function rows(tally){const names=[...new Set(tally.fighters.flatMap(f=>f.rows.map(r=>r.behavior)))];return names.map(behavior=>({behavior,corners:tally.fighters.map(f=>f.rows.find(r=>r.behavior===behavior)||{behavior,count:0,ticks:0})}));}
function text(tally,record){return ['Beetle battle behavior tally',record.winner===null?'Draw':(record.winner?'Blue':'Red')+' wins',record.reason,'Battle duration: '+(tally.ticks/60).toFixed(2)+' seconds','One tally = entering a behavior. Times are battle seconds.',...tally.fighters.flatMap((f,i)=>['',(i?'Blue':'Red')+': '+(f.name?f.name+' · ':'')+f.id,...f.rows.map(r=>r.behavior+': '+r.count+' ['+marks(r.count)+'] · '+(r.ticks/60).toFixed(2)+'s')])].join('\n');}
function cell(v){let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function csv(tally,record){return [['model','match_seed','result','battle_seconds','corner','beetle_id','beetle_name','behavior','occurrences','tally_marks','behavior_seconds','behavior_ticks'],...tally.fighters.flatMap((f,i)=>f.rows.map(r=>[record.version,record.seed,record.winner===null?'Draw':record.winner?'Blue wins':'Red wins',(tally.ticks/60).toFixed(6),i?'Blue':'Red',f.id,f.name,r.behavior,r.count,marks(r.count),(r.ticks/60).toFixed(6),r.ticks]))].map(row=>row.map(cell).join(',')).join('\r\n');}
return {labels,create,observe,snapshot,validate,marks,rows,text,csv};
});
